func rob(nums []int) int {
    if len(nums) == 1 {
        return nums[0]
    }

    memo := make([][2]int, len(nums))
    for i := range memo {
        memo[i][0] = -1
        memo[i][1] = -1
    }

    var dfs func(int, bool) int
    dfs = func(i int, flag bool) int {
        if i >= len(nums) || (flag && i == len(nums)-1) {
            return 0
        }
        flagIdx := 0
        if flag {
            flagIdx = 1
        }
        if memo[i][flagIdx] != -1 {
            return memo[i][flagIdx]
        }
        skip := dfs(i+1, flag)
        take := nums[i] + dfs(i+2, flag || i == 0)
        if skip > take {
            memo[i][flagIdx] = skip
        } else {
            memo[i][flagIdx] = take
        }
        return memo[i][flagIdx]
    }

    start0 := dfs(0, true)
    start1 := dfs(1, false)
    if start0 > start1 {
        return start0
    }
    return start1
}

