func helper(nums []int) int {
    if len(nums) == 0 {
        return 0
    }
    if len(nums) == 1 {
        return nums[0]
    }

    dp := make([]int, len(nums))
    dp[0] = nums[0]
    if nums[0] > nums[1] {
        dp[1] = nums[0]
    } else {
        dp[1] = nums[1]
    }

    for i := 2; i < len(nums); i++ {
        notRob := dp[i-1]
        rob := nums[i] + dp[i-2]
        if notRob > rob {
            dp[i] = notRob
        } else {
            dp[i] = rob
        }
    }

    return dp[len(dp)-1]
}

